uv2 = rsl.xy * 4.0*64;
tile = clamp01(1-2*max(abs(fract(uv2.x)-.5),abs(fract(uv2.y)-.5)));
windows *= 2.0 * tile*GetPixel(fract(rsl.xy * 2.0));
lav_gnd = 0;
rsl2 = project(dist) + vec3 (mov, 0.0 );
vec3 light = GetPixel(fract(rsl2 * 2.0));
ret1 =  mix(8.0 * light*clamp01(1.0 - tower),2.0 * windows *(tower * 2.0-1),clamp01(2.0 * tower-1.1)) ;
uv4 = vec2(fract(rsl.x),fract(rsl.y));
ret1 *= 1.0 + pow(sin(4.0 * (uv4.x/uv4.y) + 8.0*uTime), 24.0 ) *(q28%4 ==1)* roam_sin ;;
ret = vec3( 1.0 ) - exp(-ret1 * 2.0);
//ret = GetPixel(uv);
}
